#!/usr/bin/env node
const fs = require("fs");
const path = require("path");

const file = process.argv[2] || "README.md";
const text = fs.readFileSync(path.resolve(file), "utf8");
const matches = text.match(/TODO/g);
console.log(matches ? matches.length : 0);

